//! Python-vs-Rust parity sweep: replays every line of
//! `tests/parity_reference.txt` (generated by the frozen Python module)
//! through the Rust port and requires 0 mismatches.
//!
//! Coverage: SplitMix64 streams (next_u64 / randbelow incl. n==1 and
//! n==2^63 / random), task streams, default choices, run trajectories,
//! compiled insights (all fields), verify_lesson outcomes for every
//! insight x attribute, and per-arm solve outcomes (none / plain /
//! wikitrace, plus succ_only / fail_only subsets) — 5 seeds.

use std::collections::HashMap;
use wikitrace::*;

const REFERENCE: &str = include_str!("parity_reference.txt");

struct SeedState {
    tasks: Vec<Task>,
    runs: Vec<Run>,
    memory: Option<Memory>,
    test_tasks: Vec<Task>,
}

impl SeedState {
    fn new() -> Self {
        SeedState { tasks: Vec::new(), runs: Vec::new(), memory: None, test_tasks: Vec::new() }
    }
}

fn parse_scope(s: &str) -> Scope {
    if s == "any" {
        Scope::Any
    } else if let Some(rest) = s.strip_prefix("attr:") {
        Scope::Attr(rest.parse::<u64>().unwrap())
    } else {
        panic!("bad scope {}", s)
    }
}

fn parse_verdict(s: &str) -> Verdict {
    match s {
        "supported" => Verdict::Supported,
        "contradicted" => Verdict::Contradicted,
        "unsupported" => Verdict::Unsupported,
        "unknown" => Verdict::Unknown,
        _ => panic!("bad verdict {}", s),
    }
}

fn parse_mode(s: &str) -> Mode {
    match s {
        "none" => Mode::None,
        "plain" => Mode::Plain,
        "wikitrace" => Mode::WikiTrace,
        _ => panic!("bad mode {}", s),
    }
}

#[test]
fn parity_sweep_zero_mismatches() {
    let mut states: HashMap<u64, SeedState> = HashMap::new();
    let mut checked: usize = 0;
    let mut mismatches: Vec<String> = Vec::new();

    for (lineno, line) in REFERENCE.lines().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let f: Vec<&str> = line.split_whitespace().collect();
        match f[0] {
            "rng" => {
                let seed: u64 = f[1].parse().unwrap();
                let mut rng = SplitMix64::new(seed);
                for (i, exp) in f[2..].iter().enumerate() {
                    let got = rng.next_u64();
                    let want: u64 = exp.parse().unwrap();
                    checked += 1;
                    if got != want {
                        mismatches.push(format!("line {}: rng seed={} [{}] got {} want {}", lineno + 1, seed, i, got, want));
                    }
                }
            }
            "randbelow" => {
                let seed: u64 = f[1].parse().unwrap();
                let mut rng = SplitMix64::new(seed);
                for (n, exp) in [1u64, 2, 3, 4, 5, 7, 100, 1u64 << 63].iter().zip(f[2..].iter()) {
                    let got = rng.randbelow(*n);
                    let want: u64 = exp.parse().unwrap();
                    checked += 1;
                    if got != want {
                        mismatches.push(format!("line {}: randbelow seed={} n={} got {} want {}", lineno + 1, seed, n, got, want));
                    }
                }
            }
            "random" => {
                let seed: u64 = f[1].parse().unwrap();
                let mut rng = SplitMix64::new(seed);
                for (i, exp) in f[2..].iter().enumerate() {
                    let got = rng.random();
                    let want: f64 = exp.parse().unwrap();
                    checked += 1;
                    if got != want {
                        mismatches.push(format!("line {}: random seed={} [{}] got {} want {}", lineno + 1, seed, i, got, want));
                    }
                }
            }
            "task" => {
                let seed: u64 = f[1].parse().unwrap();
                let st = states.entry(seed).or_insert_with(SeedState::new);
                if st.tasks.is_empty() {
                    st.tasks = gen_tasks(seed, 20);
                }
                let tid: u64 = f[2].parse().unwrap();
                let want_attr: u64 = f[3].parse().unwrap();
                let got = &st.tasks[tid as usize];
                checked += 1;
                if got.tid != tid || got.attr != want_attr {
                    mismatches.push(format!("line {}: task seed={} tid={} got {:?} want attr={}", lineno + 1, seed, tid, got, want_attr));
                }
            }
            "choices" => {
                let seed: u64 = f[1].parse().unwrap();
                let st = states.entry(seed).or_insert_with(SeedState::new);
                if st.tasks.is_empty() {
                    st.tasks = gen_tasks(seed, 20);
                }
                let tid: u64 = f[2].parse().unwrap();
                let want: [u64; 3] = [f[3].parse().unwrap(), f[4].parse().unwrap(), f[5].parse().unwrap()];
                let got = default_choices(&st.tasks[tid as usize], seed);
                checked += 1;
                if got != want {
                    mismatches.push(format!("line {}: choices seed={} tid={} got {:?} want {:?}", lineno + 1, seed, tid, got, want));
                }
            }
            "step" => {
                let seed: u64 = f[1].parse().unwrap();
                let st = states.entry(seed).or_insert_with(SeedState::new);
                if st.tasks.is_empty() {
                    st.tasks = gen_tasks(seed, 20);
                }
                if st.runs.is_empty() {
                    st.runs = st.tasks.iter().map(|t| run_default(t, seed, seed + 7)).collect();
                }
                let rid: u64 = f[2].parse().unwrap();
                let step_type: u8 = f[3].parse().unwrap();
                let want_chosen: u64 = f[4].parse().unwrap();
                let want_ok: bool = f[5] == "1";
                let want_obs: bool = f[6] == "1";
                let step = &st.runs[rid as usize].steps[step_type as usize];
                checked += 1;
                if step.step_type != step_type
                    || step.chosen != want_chosen
                    || step.ok != want_ok
                    || step.observed != want_obs
                {
                    mismatches.push(format!(
                        "line {}: step seed={} rid={} st={} got {:?} want chosen={} ok={} obs={}",
                        lineno + 1, seed, rid, step_type, step, want_chosen, want_ok, want_obs
                    ));
                }
            }
            "run" => {
                let seed: u64 = f[1].parse().unwrap();
                let st = states.get(&seed).expect("runs before steps");
                let rid: u64 = f[2].parse().unwrap();
                let want_success: bool = f[3] == "1";
                let got = st.runs[rid as usize].success;
                checked += 1;
                if got != want_success {
                    mismatches.push(format!("line {}: run seed={} rid={} got {} want {}", lineno + 1, seed, rid, got, want_success));
                }
            }
            "insight" => {
                let seed: u64 = f[1].parse().unwrap();
                let st = states.entry(seed).or_insert_with(SeedState::new);
                if st.memory.is_none() {
                    if st.runs.is_empty() {
                        if st.tasks.is_empty() {
                            st.tasks = gen_tasks(seed, 20);
                        }
                        st.runs = st.tasks.iter().map(|t| run_default(t, seed, seed + 7)).collect();
                    }
                    st.memory = Some(compile_memory(st.runs.clone(), seed + 11));
                }
                let mem = st.memory.as_ref().unwrap();
                let iid = f[2];
                let ins = mem.insights.iter().find(|i| i.iid == iid).expect("insight iid");
                let want_step: u8 = f[3].parse().unwrap();
                let want_claimed: u64 = f[4].parse().unwrap();
                let want_scope = parse_scope(f[5]);
                let want_run: u64 = f[6].parse().unwrap();
                let want_succ: bool = f[7] == "1";
                let want_corr: bool = f[8] == "1";
                checked += 1;
                if ins.step_type != want_step
                    || ins.claimed != want_claimed
                    || ins.scope != want_scope
                    || ins.source_run != want_run
                    || ins.source_success != want_succ
                    || ins.corrupted != want_corr
                {
                    mismatches.push(format!(
                        "line {}: insight seed={} {} got {:?} want step={} claimed={} scope={:?} run={} succ={} corr={}",
                        lineno + 1, seed, iid, ins, want_step, want_claimed, want_scope, want_run, want_succ, want_corr
                    ));
                }
            }
            "verify" => {
                let seed: u64 = f[1].parse().unwrap();
                let st = states.get(&seed).expect("verify before memory");
                let mem = st.memory.as_ref().unwrap();
                let iid = f[2];
                let ins = mem.insights.iter().find(|i| i.iid == iid).expect("insight iid");
                let attr: u64 = f[3].parse().unwrap();
                let want_verdict = parse_verdict(f[4]);
                let want_reads: u64 = f[5].parse().unwrap();
                let (got_verdict, got_reads) = verify_lesson(ins, attr, mem);
                checked += 1;
                if got_verdict != want_verdict || got_reads != want_reads {
                    mismatches.push(format!(
                        "line {}: verify seed={} {} attr={} got {:?}/{} want {:?}/{}",
                        lineno + 1, seed, iid, attr, got_verdict, got_reads, want_verdict, want_reads
                    ));
                }
            }
            "solve" | "solve_succ" | "solve_fail" => {
                // solve:      solve <seed> <tid> <attr> <mode> <ok> <d> <c> <r> <l>
                // solve_succ: solve_succ <seed> <tid> <attr> <ok> <d> <c> <r> <l>
                let seed: u64 = f[1].parse().unwrap();
                let st = states.entry(seed).or_insert_with(SeedState::new);
                if st.memory.is_none() {
                    if st.runs.is_empty() {
                        if st.tasks.is_empty() {
                            st.tasks = gen_tasks(seed, 20);
                        }
                        st.runs = st.tasks.iter().map(|t| run_default(t, seed, seed + 7)).collect();
                    }
                    st.memory = Some(compile_memory(st.runs.clone(), seed + 11));
                }
                if st.test_tasks.is_empty() {
                    st.test_tasks = gen_tasks(seed + 5000, 40);
                }
                let mem_full = st.memory.as_ref().unwrap();
                let (mem, mode, ok_idx, d_idx, c_idx, r_idx, l_idx) = match f[0] {
                    "solve" => (mem_full.clone(), parse_mode(f[4]), 5, 6, 7, 8, 9),
                    "solve_succ" => (mem_full.subset(true), Mode::WikiTrace, 4, 5, 6, 7, 8),
                    _ => (mem_full.subset(false), Mode::WikiTrace, 4, 5, 6, 7, 8),
                };
                let tid: u64 = f[2].parse().unwrap();
                let attr: u64 = f[3].parse().unwrap();
                let task = &st.test_tasks[tid as usize];
                assert_eq!(task.tid, tid);
                assert_eq!(task.attr, attr);
                let want_ok: bool = f[ok_idx] == "1";
                let want_d: u64 = f[d_idx].parse().unwrap();
                let want_c: u64 = f[c_idx].parse().unwrap();
                let want_r: u64 = f[r_idx].parse().unwrap();
                let want_l: u64 = f[l_idx].parse().unwrap();
                let mem_arg = if mode == Mode::None { None } else { Some(&mem) };
                let (got_ok, stats) = solve(task, mem_arg, mode, seed);
                checked += 1;
                if got_ok != want_ok
                    || stats.descents != want_d
                    || stats.corrections != want_c
                    || stats.evidence_reads != want_r
                    || stats.lessons_followed != want_l
                {
                    mismatches.push(format!(
                        "line {}: {} seed={} tid={} mode={:?} got ok={} {:?} want ok={} d={} c={} r={} l={}",
                        lineno + 1, f[0], seed, tid, mode, got_ok, stats, want_ok, want_d, want_c, want_r, want_l
                    ));
                }
            }
            other => panic!("line {}: unknown record kind {}", lineno + 1, other),
        }
    }

    println!("parity sweep: {} cases checked, {} mismatches", checked, mismatches.len());
    for m in mismatches.iter().take(20) {
        println!("  MISMATCH: {}", m);
    }
    assert_eq!(checked, 3200, "expected 3200 parity cases");
    assert!(mismatches.is_empty(), "{} mismatches", mismatches.len());
}
